package com.bank.serverless;

import java.util.*;
import java.util.logging.*;

public class LambdaDecisionDemo {
    private static final Logger log = Logger.getLogger("LambdaDecision");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        WorkloadPlacement planner = new WorkloadPlacement();

        Job indexer = new Job("statement-indexer", true /*eventDriven*/, 30 /*sec*/, false /*steady*/);
        Job api = new Job("transfer-api", false, 0, true);
        Job reconcile = new Job("nightly-reconciliation", false, 40 * 60 /*2400 sec*/, false);

        for (Job j : List.of(indexer, api, reconcile)) {
            log.info(() -> j.name() + " -> " + planner.place(j));
        }

        // Demonstrate cold vs warm start for the indexer function.
        LambdaFunction fn = new LambdaFunction(800 /*cold ms*/, 15 /*warm ms*/);
        log.warning(() -> "Indexer cold start latency: " + fn.invoke(false) + " ms (new env init)");
        log.info(() -> "Indexer warm start latency: " + fn.invoke(true) + " ms (reused env)");
    }
}

// ─── Would be in WorkloadPlacement.java ───
class WorkloadPlacement {
    private static final int LAMBDA_MAX_SECONDS = 15 * 60; // 900s hard limit

    String place(Job j) {
        if (j.durationSeconds() > LAMBDA_MAX_SECONDS) {
            return "CONTAINER (exceeds Lambda 15-min limit; use ECS or Step Functions)";
        }
        if (j.eventDriven() && !j.steady()) {
            return "LAMBDA (event-driven, short, scales to zero, pay-per-ms)";
        }
        if (j.steady()) {
            return "CONTAINER (steady traffic; avoid constant cold-start latency)";
        }
        return "CONTAINER (default for long/steady workloads)";
    }
}

// ─── Would be in LambdaFunction.java ───
class LambdaFunction {
    private final int coldStartMs;
    private final int warmMs;
    LambdaFunction(int coldStartMs, int warmMs) { this.coldStartMs = coldStartMs; this.warmMs = warmMs; }
    // Cold start adds init latency; warm reuse is fast. Function is stateless.
    int invoke(boolean warm) { return warm ? warmMs : coldStartMs; }
}

// ─── Would be in Job.java ───
class Job {
    private final String name;
    private final boolean eventDriven;
    private final int durationSeconds;
    private final boolean steady;
    Job(String name, boolean eventDriven, int durationSeconds, boolean steady) {
        this.name = name; this.eventDriven = eventDriven;
        this.durationSeconds = durationSeconds; this.steady = steady;
    }
    String name() { return name; }
    boolean eventDriven() { return eventDriven; }
    int durationSeconds() { return durationSeconds; }
    boolean steady() { return steady; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
